// Status vs a given point in time: 'upcoming' | 'current' | 'ended'.
// Permanent banners (no end date) are always 'current'.
export function getRunStatus(run, now = Date.now()) {
  if (!run.end) return 'current';
  const start = Date.parse(run.start);
  const end = Date.parse(run.end);
  if (now < start) return 'upcoming';
  if (now < end) return 'current';
  return 'ended';
}

export function getBannerRuns() {
  return bannerRuns;
}

export function getCurrentRuns(now = Date.now()) {
  return bannerRuns.filter(r => getRunStatus(r, now) === 'current');
}

